package com.bank.comms;

import java.math.BigDecimal;
import java.util.logging.*;

public class CommsDemo {
    private static final Logger log = Logger.getLogger("Comms");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SyncClient sync = new SyncClient();
        AsyncBus bus = new AsyncBus();

        // Register async consumers for a completed transfer
        bus.subscribe("transfer.completed", e -> log.info(() -> "  [receipt] emailed for " + e));
        bus.subscribe("transfer.completed", e -> log.info(() -> "  [fraud] scored " + e));
        bus.subscribe("transfer.completed", e -> log.info(() -> "  [analytics] recorded " + e));

        TransferService service = new TransferService(sync, bus);

        // SYNC: balance read — caller needs the answer NOW
        BigDecimal bal = service.readBalance("SAV2001");
        log.info(() -> "SYNC balance = " + bal);

        // ASYNC: transfer returns fast; side effects happen in background
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info("transfer() returned immediately; async consumers run next:");
        bus.deliverAll();  // simulate async consumers processing the event
    }
}

