package com.bank.comms;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Synchronous request-response (REST/gRPC style): caller blocks for the answer.
public class SyncClient {
    private static final Logger log = Logger.getLogger("Comms");
    private final Map<String, BigDecimal> accountService = Map.of(
        "SAV2001", new BigDecimal("1000000"), "CUR3001", new BigDecimal("250000"));

    public BigDecimal getBalance(String accountId) {
        log.fine(() -> "SYNC call account-service for " + accountId + " (blocking)");
        // simulate a network round trip while the caller waits
        try { Thread.sleep(10); } catch (InterruptedException ignored) {}
        return accountService.get(accountId);
    }
}
```

