// ─── File: AsyncBus.java ───
package com.bank.comms;

import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

// Asynchronous pub-sub (Kafka/SQS style): publish returns immediately; consumers run later.
public class AsyncBus {
    private static final Logger log = Logger.getLogger("Comms");
    private final Map<String, List<Consumer<String>>> subscribers = new HashMap<>();
    private final Deque<String[]> pending = new ArrayDeque<>();   // topic + message

    public void subscribe(String topic, Consumer<String> handler) {
        subscribers.computeIfAbsent(topic, k -> new ArrayList<>()).add(handler);
    }
    public void publish(String topic, String message) {
        pending.add(new String[]{topic, message});   // queued, NOT processed now
        log.fine(() -> "published to " + topic + " (returns immediately)");
    }
    // simulate the broker delivering to consumers asynchronously
    public void deliverAll() {
        String[] item;
        while ((item = pending.poll()) != null) {
            for (Consumer<String> h : subscribers.getOrDefault(item[0], List.of()))
                h.accept(item[1]);
        }
    }
}
```

