// ─── File: TransferService.java ───
package com.bank.comms;

import java.math.BigDecimal;
import java.util.logging.*;

public class TransferService {
    private static final Logger log = Logger.getLogger("Comms");
    private final SyncClient sync;
    private final AsyncBus bus;

    public TransferService(SyncClient sync, AsyncBus bus) { this.sync = sync; this.bus = bus; }

    // balance read: SYNC because the caller needs the number to proceed
    public BigDecimal readBalance(String accountId) {
        return sync.getBalance(accountId);   // blocks for the answer
    }

    // transfer: do the minimal SYNC work, then defer the rest ASYNC
    public void transfer(String from, String to, BigDecimal amount) {
        // (in a real system: the actual debit/credit would be a sync, transactional step)
        log.info(() -> "SYNC: committed transfer " + from + "->" + to + " Rs." + amount);
        // defer receipt, fraud, analytics so the caller is not blocked by them
        bus.publish("transfer.completed", from + "->" + to + " Rs." + amount);
    }
}
```
